import hashlib, os
from cryptography.hazmat.primitives.asymmetric import ec, mlkem, x25519
from cryptography.hazmat.primitives import serialization

# ---- one interface, several algorithms: callers only see generate / encaps / decaps and a name ----
class KEM:
    name = "abstract"
    def generate(self): raise NotImplementedError          # -> (public key bytes, secret key object)
    def encaps(self, pk): raise NotImplementedError        # -> (ciphertext, shared secret)
    def decaps(self, sk, ct): raise NotImplementedError    # -> shared secret

def _kdf(*parts):
    h = hashlib.sha3_256()
    for p in parts: h.update(len(p).to_bytes(4, "big") + p)
    return h.digest()

class X25519KEM(KEM):
    name = "X25519"
    def generate(self):
        sk = x25519.X25519PrivateKey.generate()
        return sk.public_key().public_bytes_raw(), sk
    def encaps(self, pk):
        eph = x25519.X25519PrivateKey.generate()
        ss = eph.exchange(x25519.X25519PublicKey.from_public_bytes(pk)); ct = eph.public_key().public_bytes_raw()
        return ct, _kdf(b"x25519", ss, ct, pk)
    def decaps(self, sk, ct):
        ss = sk.exchange(x25519.X25519PublicKey.from_public_bytes(ct))
        return _kdf(b"x25519", ss, ct, sk.public_key().public_bytes_raw())

class P256KEM(KEM):
    name = "ECDH-P256"
    def generate(self):
        sk = ec.generate_private_key(ec.SECP256R1())
        return sk.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint), sk
    def encaps(self, pk):
        eph = ec.generate_private_key(ec.SECP256R1())
        peer = ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), pk)
        ct = eph.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
        return ct, _kdf(b"p256", eph.exchange(ec.ECDH(), peer), ct, pk)
    def decaps(self, sk, ct):
        peer = ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), ct)
        pk = sk.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
        return _kdf(b"p256", sk.exchange(ec.ECDH(), peer), ct, pk)

class MLKEM768KEM(KEM):
    name = "ML-KEM-768"
    def generate(self):
        sk = mlkem.MLKEM768PrivateKey.generate()
        return sk.public_key().public_bytes_raw(), sk
    def encaps(self, pk):
        ss, ct = mlkem.MLKEM768PublicKey.from_public_bytes(pk).encapsulate()
        return ct, ss
    def decaps(self, sk, ct):
        return sk.decapsulate(ct)

class HybridKEM(KEM):
    """classical + post-quantum: the secret is safe if EITHER component holds (illustrative combiner; deployed hybrids follow the IETF specifications)"""
    def __init__(self, a, b):
        self.a, self.b = a, b
        self.name = f"{a.name}+{b.name}"
    def generate(self):
        pa, sa = self.a.generate(); pb, sb = self.b.generate()
        return len(pa).to_bytes(4, "big") + pa + pb, (sa, sb, len(pa))
    def encaps(self, pk):
        n = int.from_bytes(pk[:4], "big"); pa, pb = pk[4:4 + n], pk[4 + n:]
        ca, ssa = self.a.encaps(pa); cb, ssb = self.b.encaps(pb)
        return len(ca).to_bytes(4, "big") + ca + cb, _kdf(b"hybrid", ssa, ssb, ca, cb)
    def decaps(self, sk, ct):
        sa, sb, _ = sk
        n = int.from_bytes(ct[:4], "big"); ca, cb = ct[4:4 + n], ct[4 + n:]
        return _kdf(b"hybrid", self.a.decaps(sa, ca), self.b.decaps(sb, cb), ca, cb)

REGISTRY = {k.name: k for k in (X25519KEM(), P256KEM(), MLKEM768KEM(), HybridKEM(X25519KEM(), MLKEM768KEM()))}
# The same protocol code runs with every algorithm: it depends only on the KEM interface. Adding an algorithm means registering a class, not editing callers.
def establish(kem_name):
    kem = REGISTRY[kem_name]
    pk, sk = kem.generate()
    ct, secret_sender = kem.encaps(pk)
    secret_receiver = kem.decaps(sk, ct)
    return len(pk), len(ct), secret_sender == secret_receiver
print(f"{'algorithm':<28} {'public key (bytes)':>18} {'ciphertext (bytes)':>19}  secrets agree")
for name in REGISTRY:
    pk, ct, ok = establish(name)
    print(f"{name:<28} {pk:>18} {ct:>19}  {ok}")
print()
# add a new algorithm WITHOUT touching establish(): ML-KEM-1024 from the same library
class MLKEM1024KEM(KEM):
    name = "ML-KEM-1024"
    def generate(self):
        sk = mlkem.MLKEM1024PrivateKey.generate(); return sk.public_key().public_bytes_raw(), sk
    def encaps(self, pk):
        ss, ct = mlkem.MLKEM1024PublicKey.from_public_bytes(pk).encapsulate(); return ct, ss
    def decaps(self, sk, ct): return sk.decapsulate(ct)
REGISTRY["ML-KEM-1024"] = MLKEM1024KEM()
pk, ct, ok = establish("ML-KEM-1024")
print(f"after registering one new class, the unchanged establish() works with ML-KEM-1024: public key {pk} bytes, ciphertext {ct} bytes, secrets agree: {ok}")
print()
print("what the interface hides and what it cannot hide:")
print("  hidden: algorithm-specific key objects, encodings and the combiner of the hybrid")
print("  not hidden: sizes. The ML-KEM-768 public key is", round(len(REGISTRY['ML-KEM-768'].generate()[0]) / 32), "times the X25519 key; protocols, buffers, certificates and database columns that assumed 32 bytes must be reviewed")

