from cryptography.hazmat.primitives.ciphers.aead import AESGCM
# A self-describing envelope: the algorithm id travels with the ciphertext and is authenticated, so old data stays readable after the default changes, and policy can refuse algorithms.
ALG_IDS = {1: "X25519", 2: "ECDH-P256", 3: "ML-KEM-768", 4: "X25519+ML-KEM-768"}
ID_OF = {v: k for k, v in ALG_IDS.items()}
def seal(pk, data, alg):
    kem = REGISTRY[alg]
    ct, secret = kem.encaps(pk)
    header = bytes([1, ID_OF[alg]])                                   # format version 1, algorithm id
    nonce = os.urandom(12)
    body = AESGCM(secret).encrypt(nonce, data, header)                # header is authenticated (additional data)
    return header + len(ct).to_bytes(4, "big") + ct + nonce + body
def open_(sk, blob, allowed):
    version, alg_id = blob[0], blob[1]
