    if alg_id not in ALG_IDS: raise ValueError(f"unknown algorithm id {alg_id}")
    alg = ALG_IDS[alg_id]
    if alg not in allowed: raise PermissionError(f"policy refuses {alg}")
    n = int.from_bytes(blob[2:6], "big"); ct = blob[6:6 + n]; nonce = blob[6 + n:18 + n]; body = blob[18 + n:]
    secret = REGISTRY[alg].decaps(sk, ct)
    return AESGCM(secret).decrypt(nonce, body, blob[:2])
