import json
# Algorithm choice from configuration. The configuration is validated and fails CLOSED: an invalid policy is rejected and the previous valid policy stays in force.
CATALOGUE = {"key_exchange": {"X25519", "ECDH-P256", "ML-KEM-768", "X25519+ML-KEM-768"}, "signature": {"RSA-2048", "ECDSA-P256", "ML-DSA-65", "ECDSA-P256+ML-DSA-65"}}
POLICY_V1 = json.dumps({"version": 1, "rules": {"key_exchange": {"preferred": ["X25519"], "allowed": ["X25519", "ECDH-P256"]}, "signature": {"preferred": ["ECDSA-P256"], "allowed": ["RSA-2048", "ECDSA-P256"]}}})
POLICY_V2 = json.dumps({"version": 2, "rules": {"key_exchange": {"preferred": ["X25519+ML-KEM-768", "X25519"], "allowed": ["X25519+ML-KEM-768", "X25519"], "disallowed": ["ECDH-P256"]}, "signature": {"preferred": ["ECDSA-P256"], "allowed": ["RSA-2048", "ECDSA-P256"]}}})
POLICY_BAD = json.dumps({"version": 3, "rules": {"key_exchange": {"preferred": ["ML-KEM-512"], "allowed": ["X25519"]}}})
class Policy:
    def __init__(self): self.active, self.log = None, []
    def load(self, text):
        try:
            doc = json.loads(text)
            for use, rule in doc["rules"].items():
                if use not in CATALOGUE: raise ValueError(f"unknown use case {use}")
                for alg in rule["preferred"] + rule["allowed"]:
                    if alg not in CATALOGUE[use]: raise ValueError(f"{alg} is not in the algorithm catalogue")
                for alg in rule["preferred"]:
                    if alg not in rule["allowed"]: raise ValueError(f"preferred {alg} is not allowed")
                    if alg in rule.get("disallowed", []): raise ValueError(f"preferred {alg} is disallowed")
            self.active = doc; self.log.append(f"v{doc['version']} accepted")
        except (ValueError, KeyError, json.JSONDecodeError) as e:
            self.log.append(f"REJECTED, previous policy stays in force: {e}")
    def choose(self, use, peer_supports):
        rule = self.active["rules"][use]
        for alg in rule["preferred"] + [a for a in rule["allowed"] if a not in rule["preferred"]]:
            if alg in peer_supports: return alg
        return None
p = Policy()
peers = {"modern client": {"X25519+ML-KEM-768", "X25519", "ECDH-P256"}, "older client": {"X25519", "ECDH-P256"}, "legacy client": {"ECDH-P256"}}
def table(title):
    print(f"-- {title}")
    for peer, supports in peers.items():
        print(f"   {peer:<14} key exchange -> {p.choose('key_exchange', supports)}")
p.load(POLICY_V1); table("policy v1 in force")
p.load(POLICY_V2); table("after changing ONLY the configuration to v2 (no code change, no redeploy)")
p.load(POLICY_BAD); table("after an invalid v3 was offered (still v2)")
print()
for line in p.log: print("audit:", line)
print("the legacy client now gets None: the connection is refused, which is a visible, intended effect of the policy; discovery (E2) tells you beforehand how many such clients exist")

