from cryptography.hazmat.primitives.ciphers.aead import AESGCM
# A key store behind an interface: keys have identifiers, an algorithm and a state, and records refer to key ids. Rotation to a new algorithm needs no change in the callers.
class KeyStore:
    def __init__(self): self.keys, self.n = {}, 0
    def create(self, purpose, alg):
        self.n += 1; kid = f"{purpose}-{self.n}"
        pk, sk = REGISTRY[alg].generate()
        self.keys[kid] = {"purpose": purpose, "alg": alg, "state": "pre-active", "pk": pk, "sk": sk}
        return kid
    def activate(self, kid):
        for k in self.keys.values():
            if k["purpose"] == self.keys[kid]["purpose"] and k["state"] == "active": k["state"] = "deprecated (decrypt only)"
        self.keys[kid]["state"] = "active"
    def current(self, purpose): return next(k_id for k_id, k in self.keys.items() if k["purpose"] == purpose and k["state"] == "active")
    def destroy(self, kid): self.keys[kid]["state"] = "destroyed"; self.keys[kid]["sk"] = None
def protect(store, purpose, data):
    kid = store.current(purpose); k = store.keys[kid]
    ct, secret = REGISTRY[k["alg"]].encaps(k["pk"])
    nonce = os.urandom(12)
    return {"kid": kid, "ct": ct, "nonce": nonce, "body": AESGCM(secret).encrypt(nonce, data, kid.encode())}
def unprotect(store, rec):
    k = store.keys[rec["kid"]]
    if k["state"] == "destroyed": raise LookupError("key destroyed")
    return AESGCM(REGISTRY[k["alg"]].decaps(k["sk"], rec["ct"])).decrypt(rec["nonce"], rec["body"], rec["kid"].encode())
def report(store, title):
    print(f"-- {title}")
    for kid, k in store.keys.items(): print(f"   {kid:<15} {k['alg']:<20} {k['state']}")
store = KeyStore()
k1 = store.create("customer-data", "X25519"); store.activate(k1)
records = [protect(store, "customer-data", f"record {i}".encode()) for i in range(5)]
report(store, "before rotation")
k2 = store.create("customer-data", "X25519+ML-KEM-768"); store.activate(k2)
new_rec = protect(store, "customer-data", b"record 5")
report(store, "after rotation to the hybrid (callers unchanged)")
print("old records readable with the deprecated key:", all(unprotect(store, r) == f"record {i}".encode() for i, r in enumerate(records)), "| new record uses", new_rec["kid"])
migrated = [protect(store, "customer-data", unprotect(store, r)) for r in records]
store.destroy(k1)
report(store, "after re-protecting the old records and destroying the old key")
print("migrated records readable:", all(unprotect(store, r) == f"record {i}".encode() for i, r in enumerate(migrated)))
try: unprotect(store, records[0])
except LookupError as e: print("an un-migrated record is now unreadable:", e, "-> destroy a key only after the re-protection job is verified complete")
print("records per key id:", {kid: sum(1 for r in migrated + [new_rec] if r['kid'] == kid) for kid in store.keys})

import datetime, os, socket, ssl, tempfile, threading
from cryptography import x509
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec, mldsa, rsa
from cryptography.x509.oid import NameOID
# One issuing pipeline, several certificate algorithms. The issuance PROFILE names the key type; nothing else in the pipeline changes.
now = datetime.datetime.now(datetime.timezone.utc)
def name(cn): return x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, cn)])
def new_key(profile):
    return {"rsa-2048": lambda: rsa.generate_private_key(65537, 2048), "ecdsa-p256": lambda: ec.generate_private_key(ec.SECP256R1()), "ml-dsa-65": lambda: mldsa.MLDSA65PrivateKey.generate()}[profile]()
def sign_hash(key): return None if isinstance(key, mldsa.MLDSA65PrivateKey) else hashes.SHA256()
def issue(subject_cn, subject_key, issuer_cn, issuer_key, ca=False, days=90):
    b = (x509.CertificateBuilder().subject_name(name(subject_cn)).issuer_name(name(issuer_cn)).public_key(subject_key.public_key()).serial_number(x509.random_serial_number())
         .not_valid_before(now - datetime.timedelta(minutes=1)).not_valid_after(now + datetime.timedelta(days=days))
