import ast, hashlib
# Where do cryptographic calls live? Count call sites that bypass a crypto boundary, then retrofit with a thin wrapper and show that one change in the boundary switches every caller. Sample code (DEMO DATA).
BEFORE = {
 "orders.py": "import hashlib\ndef order_id(x): return hashlib.sha1(x.encode()).hexdigest()\n",
 "export.py": "import hashlib\ndef checksum(b): return hashlib.sha1(b).hexdigest()\ndef sign_name(n): return hashlib.md5(n.encode()).hexdigest()\n",
 "audit.py": "import hashlib\ndef log_hash(line): return hashlib.sha256(line.encode()).hexdigest()\n",
}
AFTER = {
 "orders.py": "import cryptoapi\ndef order_id(x): return cryptoapi.digest(x.encode())\n",
 "export.py": "import cryptoapi\ndef checksum(b): return cryptoapi.digest(b)\ndef sign_name(n): return cryptoapi.digest(n.encode())\n",
 "audit.py": "import cryptoapi\ndef log_hash(line): return cryptoapi.digest(line.encode())\n",
}
def direct_calls(files):
    found = []
    for fname, src in files.items():
        for node in ast.walk(ast.parse(src)):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and ast.unparse(node.func.value) == "hashlib":
                found.append((fname, node.lineno, ast.unparse(node.func)))
    return sorted(found)
b, a = direct_calls(BEFORE), direct_calls(AFTER)
print(f"before the retrofit: {len(b)} direct cryptographic calls scattered over {len(set(f for f, _, _ in b))} files, with algorithms {sorted({x for _, _, x in b})}")
for f, l, c in b: print(f"   {f}:{l} {c}")
print(f"after the retrofit:  {len(a)} direct calls in application code (all go through the boundary module)")
print()
# the boundary: one place that decides the algorithm
class Boundary:
    algorithm = "sha256"
    @classmethod
    def digest(cls, data): return hashlib.new(cls.algorithm, data).hexdigest()
import types
cryptoapi = types.ModuleType("cryptoapi"); cryptoapi.digest = Boundary.digest
import sys; sys.modules["cryptoapi"] = cryptoapi
ns = {}
for fname, src in AFTER.items(): exec(src, ns)
print("application output with the boundary set to sha256:  ", ns["order_id"]("A-100")[:24], "...")
Boundary.algorithm = "sha3_256"
print("after ONE change in the boundary (sha3_256):         ", ns["order_id"]("A-100")[:24], "...  (all", len(AFTER), "files changed behaviour, none was edited)")
